*Goal:* A Go package turns a voice-summary transcript into a validated {{model.Proposal}}: it builds the prompt (transcript, attack, medicine list, timezone, recording time), asks the model for structured output, and drops or repairs anything invalid with a warning. It never guesses a medicine.

*Files:*

* Create: {{backend/internal/extract/prompt.go}} (system prompt, user message, schema)
* Create: {{backend/internal/extract/validate.go}} ({{Raw}}, {{Validate}})
* Create: {{backend/internal/extract/extractor.go}} ({{Extractor}}, {{Input}}, {{PromptVersion}})
* Test: {{backend/internal/extract/validate_test.go}}, {{backend/internal/extract/extractor_test.go}}

*Interfaces:*

* Consumes: {{llm.Client}} and {{mocks.NewClient(t)}} (T-V1); {{model.Attack}}, {{model.Medication}}, {{model.Proposal}}, {{model.ProposedDose}}, {{model.UnknownMedication}}, {{model.Symptom}}, {{model.Symptoms}} (T-S2).
* Produces:

{code:go}package extract

const PromptVersion = "1"

type Input struct {
	Transcript  string
	Attack      model.Attack
	Medications []model.Medication
	RecordedAt  time.Time
}

type RawDose struct {
	Medication string   `json:"medication"`
	Amount     *float64 `json:"amount"`
	TakenAt    *string  `json:"taken_at"`
}

type Raw struct {
	StartedAt    *string   `json:"started_at"`
	EndedAt      *string   `json:"ended_at"`
	PeakSeverity *int      `json:"peak_severity"`
	Symptoms     []string  `json:"symptoms"`
	Doses        []RawDose `json:"doses"`
	Notes        *string   `json:"notes"`
}

func Validate(raw Raw, attack model.Attack, meds []model.Medication, recordedAt time.Time) model.Proposal

func New(client llm.Client) *Extractor
func (e *Extractor) Extract(ctx context.Context, in Input) (model.Proposal, error)
func (e *Extractor) ModelName() string{code}

Validation rules (all produce a warning string in {{Proposal.Warnings}} unless noted):

{noformat}| Input | Result |
|---|---|
| `started_at` / `ended_at` / dose `taken_at` not RFC 3339 | dropped: `dropped <field>: not a valid time` |
| a time after `recordedAt` | dropped: `dropped <field>: after the recording time` |
| a time more than 7 days before `recordedAt` | dropped: `dropped <field>: more than 7 days before the recording` |
| `ended_at` before the effective start (proposed `started_at`, else `attack.StartedAt`) | dropped: `dropped ended_at: before the start` |
| `peak_severity` outside 0 to 10 | dropped: `dropped peak_severity: <n> is outside 0 to 10` |
| symptom not in `model.Symptoms` (after trim and lower-case) | dropped: `dropped unknown symptom "<s>"` |
| duplicate symptom | kept once, no warning |
| dose medicine name equal (case-insensitive, trimmed) to a non-archived medicine | `ProposedDose` with that medicine's id |
| dose medicine name with no exact match (including nicknames like "riza") | `UnknownMedication{Name, Amount, TakenAt}`, no warning; never fuzzy-matched |
| matched dose with `amount` null | usual amount, no warning |
| matched dose with `amount` <= 0 | usual amount: `used usual amount for <name>: <n> is not a positive amount` |
| matched dose with `taken_at` null or dropped | effective start: `used attack start as the time for <name>` |
| `notes` empty after trim | null, no warning |{noformat}

All times in the result are converted to UTC. All slices in the result are non-nil.

* [ ] *Step 1: Write the failing validation test* {{backend/internal/extract/validate_test.go}}:

{code:go}package extract_test

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"

	"github.com/tahardi/halo/backend/internal/extract"
	"github.com/tahardi/halo/backend/internal/model"
)

var (
	recordedAt = time.Date(2026, 10, 13, 16, 30, 0, 0, time.UTC)
	attackStart = time.Date(2026, 10, 13, 7, 0, 0, 0, time.UTC)
)

func meds() []model.Medication {
	return []model.Medication{
		{ID: "med-riza", Name: "Rizatriptan", UsualAmount: 1, Unit: "tablet", Kind: model.MedicationAcute},
		{ID: "med-ibu", Name: "Ibuprofen", UsualAmount: 400, Unit: "mg", Kind: model.MedicationAcute},
		{ID: "med-old", Name: "Sumatriptan", UsualAmount: 1, Unit: "tablet", Kind: model.MedicationAcute, Archived: true},
	}
}

func attack() model.Attack {
	return model.Attack{ID: "a1", StartedAt: attackStart, Timezone: "America/New_York"}
}

func empty() model.Proposal {
	return model.Proposal{
		Symptoms:           []model.Symptom{},
		Doses:              []model.ProposedDose{},
		UnknownMedications: []model.UnknownMedication{},
		Warnings:           []string{},
	}
}

func ts(s string) *string { return &s }

func num(f float64) *float64 { return &f }

func sev(n int) *int { return &n }

func at(t time.Time) *time.Time { return &t }

func TestValidate(t *testing.T) {
	tests := []struct {
		name string
		raw  extract.Raw
		want func(p *model.Proposal)
	}{
		{
			name: "happy path - nothing stated",
			raw:  extract.Raw{},
			want: func(_ *model.Proposal) {},
		},
		{
			name: "happy path - times converted to utc",
			raw: extract.Raw{
				StartedAt: ts("2026-10-13T03:00:00-04:00"),
				EndedAt:   ts("2026-10-13T11:00:00-04:00"),
			},
			want: func(p *model.Proposal) {
				p.StartedAt = at(time.Date(2026, 10, 13, 7, 0, 0, 0, time.UTC))
				p.EndedAt = at(time.Date(2026, 10, 13, 15, 0, 0, 0, time.UTC))
			},
		},
		{
			name: "error - time after recording dropped",
			raw:  extract.Raw{EndedAt: ts("2026-10-13T23:00:00-04:00")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped ended_at: after the recording time"}
			},
		},
		{
			name: "error - time more than 7 days before recording dropped",
			raw:  extract.Raw{StartedAt: ts("2026-10-01T03:00:00-04:00")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped started_at: more than 7 days before the recording"}
			},
		},
		{
			name: "error - time not rfc 3339 dropped",
			raw:  extract.Raw{StartedAt: ts("3 AM")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped started_at: not a valid time"}
			},
		},
		{
			name: "error - end before attack start dropped",
			raw:  extract.Raw{EndedAt: ts("2026-10-13T02:00:00-04:00")},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped ended_at: before the start"}
			},
		},
		{
			name: "error - severity out of range dropped",
			raw:  extract.Raw{PeakSeverity: sev(11)},
			want: func(p *model.Proposal) {
				p.Warnings = []string{"dropped peak_severity: 11 is outside 0 to 10"}
			},
		},
		{
			name: "happy path - severity kept",
			raw:  extract.Raw{PeakSeverity: sev(8)},
			want: func(p *model.Proposal) { p.PeakSeverity = sev(8) },
		},
		{
			name: "happy path - symptoms cleaned and deduplicated",
			raw:  extract.Raw{Symptoms: []string{" Vomiting", "nausea", "vomiting", "hiccups"}},
			want: func(p *model.Proposal) {
				p.Symptoms = []model.Symptom{model.SymptomVomiting, model.SymptomNausea}
				p.Warnings = []string{`dropped unknown symptom "hiccups"`}
			},
		},
		{
			name: "happy path - dose matched case-insensitively",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: " rizatriptan ", Amount: num(1), TakenAt: ts("2026-10-13T03:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{MedicationID: "med-riza", Amount: 1, TakenAt: attackStart}}
			},
		},
		{
			name: "happy path - nickname is unknown never fuzzy matched",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "riza", Amount: nil, TakenAt: ts("2026-10-13T06:00:00-04:00")},
				{Medication: "my triptan", Amount: num(1), TakenAt: nil},
			}},
			want: func(p *model.Proposal) {
				p.UnknownMedications = []model.UnknownMedication{
					{Name: "riza", TakenAt: at(time.Date(2026, 10, 13, 10, 0, 0, 0, time.UTC))},
					{Name: "my triptan", Amount: num(1)},
				}
			},
		},
		{
			name: "happy path - archived medicine is unknown",
			raw:  extract.Raw{Doses: []extract.RawDose{{Medication: "Sumatriptan"}}},
			want: func(p *model.Proposal) {
				p.UnknownMedications = []model.UnknownMedication{{Name: "Sumatriptan"}}
			},
		},
		{
			name: "happy path - missing amount uses usual amount",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "Ibuprofen", TakenAt: ts("2026-10-13T06:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{
					MedicationID: "med-ibu",
					Amount:       400,
					TakenAt:      time.Date(2026, 10, 13, 10, 0, 0, 0, time.UTC),
				}}
			},
		},
		{
			name: "error - non-positive amount uses usual amount",
			raw: extract.Raw{Doses: []extract.RawDose{
				{Medication: "Ibuprofen", Amount: num(0), TakenAt: ts("2026-10-13T06:00:00-04:00")},
			}},
			want: func(p *model.Proposal) {
				p.Doses = []model.ProposedDose{{
					MedicationID: "med-ibu",
					Amount:       400,
