{code:go}package extract

import (
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/tahardi/halo/backend/internal/model"
)

const (
	maxLookback = 7 * 24 * time.Hour
	maxSeverity = 10
)

type RawDose struct {
	Medication string   `json:"medication"`
	Amount     *float64 `json:"amount"`
	TakenAt    *string  `json:"taken_at"`
}

type Raw struct {
	StartedAt    *string   `json:"started_at"`
	EndedAt      *string   `json:"ended_at"`
	PeakSeverity *int      `json:"peak_severity"`
	Symptoms     []string  `json:"symptoms"`
	Doses        []RawDose `json:"doses"`
	Notes        *string   `json:"notes"`
}

type validator struct {
	recordedAt time.Time
	warnings   []string
}

func Validate(raw Raw, attack model.Attack, meds []model.Medication, recordedAt time.Time) model.Proposal {
	v := &validator{recordedAt: recordedAt, warnings: []string{}}
	p := model.Proposal{
		Symptoms:           []model.Symptom{},
		Doses:              []model.ProposedDose{},
		UnknownMedications: []model.UnknownMedication{},
	}

	p.StartedAt = v.time("started_at", raw.StartedAt)
	start := attack.StartedAt.UTC()
	if p.StartedAt != nil {
		start = *p.StartedAt
	}
	p.EndedAt = v.time("ended_at", raw.EndedAt)
	if p.EndedAt != nil && p.EndedAt.Before(start) {
		v.warn("dropped ended_at: before the start")
		p.EndedAt = nil
	}

	if raw.PeakSeverity != nil {
		if *raw.PeakSeverity < 0 || *raw.PeakSeverity > maxSeverity {
			v.warn(fmt.Sprintf("dropped peak_severity: %d is outside 0 to 10", *raw.PeakSeverity))
		} else {
			p.PeakSeverity = raw.PeakSeverity
		}
	}

	for _, s := range raw.Symptoms {
		sym := model.Symptom(strings.ToLower(strings.TrimSpace(s)))
		if !sym.Valid() {
			v.warn(fmt.Sprintf("dropped unknown symptom %q", strings.TrimSpace(s)))
			continue
		}
		if !slices.Contains(p.Symptoms, sym) {
			p.Symptoms = append(p.Symptoms, sym)
		}
	}

	for _, d := range raw.Doses {
		name := strings.TrimSpace(d.Medication)
		med, ok := findMedication(meds, name)
		if !ok {
			p.UnknownMedications = append(p.UnknownMedications, model.UnknownMedication{
				Name:    name,
				Amount:  d.Amount,
				TakenAt: v.time("taken_at for "+name, d.TakenAt),
			})
			continue
		}
		amount := med.UsualAmount
		if d.Amount != nil {
			if *d.Amount > 0 {
				amount = *d.Amount
			} else {
				v.warn(fmt.Sprintf("used usual amount for %s: %g is not a positive amount", med.Name, *d.Amount))
			}
		}
		takenAt := v.time("taken_at for "+med.Name, d.TakenAt)
		if takenAt == nil {
			v.warn("used attack start as the time for " + med.Name)
			takenAt = &start
		}
		p.Doses = append(p.Doses, model.ProposedDose{MedicationID: med.ID, Amount: amount, TakenAt: *takenAt})
	}

	if raw.Notes != nil {
		if n := strings.TrimSpace(*raw.Notes); n != "" {
			p.Notes = &n
		}
	}

	p.Warnings = v.warnings
	return p
}

func (v *validator) warn(msg string) {
	v.warnings = append(v.warnings, msg)
}

func (v *validator) time(field string, raw *string) *time.Time {
	if raw == nil {
		return nil
	}
	t, err := time.Parse(time.RFC3339, strings.TrimSpace(*raw))
	switch {
	case err != nil:
		v.warn("dropped " + field + ": not a valid time")
		return nil
	case t.After(v.recordedAt):
		v.warn("dropped " + field + ": after the recording time")
		return nil
	case t.Before(v.recordedAt.Add(-maxLookback)):
		v.warn("dropped " + field + ": more than 7 days before the recording")
		return nil
	}
	t = t.UTC()
	return &t
}

func findMedication(meds []model.Medication, name string) (model.Medication, bool) {
	for _, m := range meds {
		if !m.Archived && strings.EqualFold(strings.TrimSpace(m.Name), name) {
			return m, true
		}
	}
	return model.Medication{}, false
}{code}

Note: a dose whose time is missing produces only the "used attack start" warning; a dose whose time is invalid produces the "dropped taken_at for <name>" warning first. Unknown medicines with an invalid time also get the "dropped taken_at for <name>" warning.

