{code:go}package extract

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/tahardi/halo/backend/internal/model"
)

const systemPrompt = `You turn a spoken summary of one migraine attack into proposed updates to that attack's record.
You receive the speaker's timezone, the time the summary was recorded, the attack as currently stored, the speaker's
list of medicines, and a transcript.

Rules:
- Propose only what the speaker clearly stated. Leave a field null, or a list empty, when it was not said.
- Times: write every time as RFC 3339 with the offset of the speaker's timezone. A spoken time without a date
  ("woke up at three") means the most recent such time at or before the recording time, never in the future.
  "Last night" and "this morning" are relative to the recording time.
- started_at is when the attack began; ended_at is when it ended. Do not repeat the stored values unless the speaker
  changed them.
- peak_severity is the worst pain on a 0 to 10 scale, only if the speaker gave a number or a clear equivalent.
- symptoms uses only the allowed values in the schema.
- doses lists each medicine taken, one entry per dose. medication is the name exactly as it appears in the medicine
  list when the speaker clearly means that medicine; otherwise the name as spoken. Never guess a medicine from a
  nickname or a drug class. amount is the number of units if stated, otherwise null. taken_at is null if no time was
  said.
- notes is one to three plain sentences in the first person with context the speaker gave about the attack or the
  hours before it (sleep, food, drink, exercise, stress, travel), or null if none.`

type promptAttack struct {
	StartedAt     string   `json:"started_at"`
	EndedAt       *string  `json:"ended_at"`
	PeakSeverity  *int     `json:"peak_severity"`
	Symptoms      []string `json:"symptoms"`
	SymptomsOther *string  `json:"symptoms_other"`
	Notes         *string  `json:"notes"`
}

type promptMedication struct {
	Name        string  `json:"name"`
	UsualAmount float64 `json:"usual_amount"`
	Unit        string  `json:"unit"`
}

func nullable(t string) map[string]any {
	return map[string]any{"type": []string{t, "null"}}
}

func object(properties map[string]any) map[string]any {
	required := make([]string, 0, len(properties))
	for k := range properties {
		required = append(required, k)
	}
	return map[string]any{
		"type":                 "object",
		"additionalProperties": false,
		"required":             required,
		"properties":           properties,
	}
}

func symptomEnum() []string {
	out := make([]string, 0, len(model.Symptoms))
	for _, s := range model.Symptoms {
		out = append(out, string(s))
	}
	return out
}

var schema = object(map[string]any{
	"started_at":    nullable("string"),
	"ended_at":      nullable("string"),
	"peak_severity": nullable("integer"),
	"symptoms": map[string]any{
		"type":  "array",
		"items": map[string]any{"type": "string", "enum": symptomEnum()},
	},
	"doses": map[string]any{
		"type": "array",
		"items": object(map[string]any{
			"medication": map[string]any{"type": "string"},
			"amount":     nullable("number"),
			"taken_at":   nullable("string"),
		}),
	},
	"notes": nullable("string"),
})

func location(name string) *time.Location {
	loc, err := time.LoadLocation(name)
	if err != nil || name == "" {
		return time.UTC
	}
	return loc
}

func userMessage(in Input) (string, error) {
	loc := location(in.Attack.Timezone)
	local := func(t time.Time) string { return t.In(loc).Format(time.RFC3339) }

	a := promptAttack{
		StartedAt:     local(in.Attack.StartedAt),
		PeakSeverity:  in.Attack.PeakSeverity,
		Symptoms:      []string{},
		SymptomsOther: in.Attack.SymptomsOther,
		Notes:         in.Attack.Notes,
	}
	if in.Attack.EndedAt != nil {
		e := local(*in.Attack.EndedAt)
		a.EndedAt = &e
	}
	for _, s := range in.Attack.Symptoms {
		a.Symptoms = append(a.Symptoms, string(s))
	}
	meds := []promptMedication{}
	for _, m := range in.Medications {
		if !m.Archived {
			meds = append(meds, promptMedication{Name: m.Name, UsualAmount: m.UsualAmount, Unit: m.Unit})
		}
	}

	attackJSON, err := json.Marshal(a)
	if err != nil {
		return "", fmt.Errorf("encoding attack: %w", err)
	}
	medsJSON, err := json.Marshal(meds)
	if err != nil {
		return "", fmt.Errorf("encoding medications: %w", err)
	}

	var b strings.Builder
	fmt.Fprintf(&b, "Timezone: %s\n", loc.String())
	fmt.Fprintf(&b, "Recorded at: %s (%s)\n\n", local(in.RecordedAt), in.RecordedAt.In(loc).Weekday())
	fmt.Fprintf(&b, "Attack:\n%s\n\n", attackJSON)
	fmt.Fprintf(&b, "Medicines:\n%s\n\n", medsJSON)
	fmt.Fprintf(&b, "Transcript:\n%s", in.Transcript)
	return b.String(), nil
}{code}

